const cards=[...document.querySelectorAll('.shot')],count=document.querySelector('#result-count');
for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{for(const peer of document.querySelectorAll('[data-filter]'))peer.setAttribute('aria-pressed',String(peer===button));for(const card of cards)card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter;const n=cards.filter(c=>!c.hidden).length;count.textContent=n+' screenshot'+(n===1?'':'s');});
const dialog=document.querySelector('#image-viewer'),image=document.querySelector('#viewer-image');let opener;
for(const link of document.querySelectorAll('.shot-preview'))link.addEventListener('click',event=>{if(event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||typeof dialog.showModal!=='function')return;event.preventDefault();opener=link;document.querySelector('#viewer-title').textContent=link.dataset.title;document.querySelector('#viewer-caption').textContent=link.dataset.caption;image.src=link.href;image.alt=link.dataset.title;document.querySelector('#viewer-original').href=link.href;document.querySelector('.viewer-image').scrollTop=0;dialog.showModal();});
document.querySelector('#close-viewer').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
